import raw from './sigma-reference.json';

/**
 * Sigma logsource, field, and modifier reference data.
 *
 * The dataset is a derived copy of the public-domain Sigma specification
 * appendices, generated by `scripts/build-sigma-reference.mjs`. It is authoring
 * reference only: nothing here validates a rule, and a logsource value that is
 * absent from this snapshot is not necessarily invalid.
 */

export const SIGMA_REFERENCE_SCHEMA_VERSION = 1;
export const SIGMA_MAX_REFERENCE_RESULTS = 100;

export type SigmaLogSourcePart = 'product' | 'category' | 'service';

export interface SigmaLogSourceRef {
  product: string;
  category: string;
  service: string;
  description: string;
}

export interface SigmaFieldRef {
  name: string;
  description: string;
  example: string;
  categories: string[];
  products: string[];
  services: string[];
}

export interface SigmaModifierRef {
  name: string;
  group: string;
  description: string;
}

export interface SigmaReferenceDataset {
  schemaVersion: number;
  specVersion: string;
  released: string;
  retrieved: string;
  source: string;
  sourcePath: string;
  sourceSha256: string;
  modifiersPath: string;
  modifiersSha256: string;
  license: string;
  logSources: SigmaLogSourceRef[];
  fields: SigmaFieldRef[];
  modifiers: SigmaModifierRef[];
}

export interface SigmaLogSourceSearchOptions {
  product?: string;
  category?: string;
  service?: string;
  limit?: number;
}

export interface SigmaFieldSearchOptions {
  logSource?: SigmaLogSourceRef;
  category?: string;
  limit?: number;
}

export interface SigmaModifierSearchOptions {
  localTestOnly?: boolean;
  limit?: number;
}

export class SigmaReferenceError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SigmaReferenceError';
  }
}

/**
 * Modifiers the local subset evaluator understands. Everything else is valid
 * Sigma but is rejected by local testing with a visible diagnostic.
 */
export const SIGMA_LOCAL_TEST_MODIFIERS: ReadonlySet<string> = new Set([
  'all',
  'any',
  'cased',
  'contains',
  'endswith',
  'startswith',
]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function cleanText(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function cleanList(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  const cleaned: string[] = [];
  const seen = new Set<string>();
  for (const item of value) {
    const text = cleanText(item).toLowerCase();
    if (text.length === 0 || seen.has(text)) continue;
    seen.add(text);
    cleaned.push(text);
  }
  return cleaned;
}

function normalizeLogSources(value: unknown): SigmaLogSourceRef[] {
  if (!Array.isArray(value)) return [];
  const entries: SigmaLogSourceRef[] = [];
  const seen = new Set<string>();
  for (const item of value) {
    if (!isRecord(item)) continue;
    const entry: SigmaLogSourceRef = {
      product: cleanText(item.product).toLowerCase(),
      category: cleanText(item.category).toLowerCase(),
      service: cleanText(item.service).toLowerCase(),
      description: cleanText(item.description),
    };
    if (!entry.product && !entry.category && !entry.service) continue;
    const key = logSourceKey(entry);
    if (seen.has(key)) continue;
    seen.add(key);
    entries.push(entry);
  }
  return entries;
}

function normalizeFields(value: unknown): SigmaFieldRef[] {
  if (!Array.isArray(value)) return [];
  const entries: SigmaFieldRef[] = [];
  const seen = new Set<string>();
  for (const item of value) {
    if (!isRecord(item)) continue;
    const name = cleanText(item.name);
    if (name.length === 0) continue;
    const entry: SigmaFieldRef = {
      name,
      description: cleanText(item.description),
      example: cleanText(item.example),
      categories: cleanList(item.categories),
      products: cleanList(item.products),
      services: cleanList(item.services),
    };
    if (entry.categories.length + entry.products.length + entry.services.length === 0) continue;
    const key = `${entry.name}|${entry.categories.join(',')}|${entry.products.join(',')}|${entry.services.join(',')}`;
    if (seen.has(key)) continue;
    seen.add(key);
    entries.push(entry);
  }
  return entries;
}

function normalizeModifiers(value: unknown): SigmaModifierRef[] {
  if (!Array.isArray(value)) return [];
  const entries: SigmaModifierRef[] = [];
  const seen = new Set<string>();
  for (const item of value) {
    if (!isRecord(item)) continue;
    const name = cleanText(item.name).toLowerCase();
    if (name.length === 0 || seen.has(name)) continue;
    seen.add(name);
    entries.push({
      name,
      group: cleanText(item.group),
      description: cleanText(item.description),
    });
  }
  return entries;
}

/** Accept only a well-formed snapshot; a corrupt file should not crash the view. */
export function normalizeSigmaReference(value: unknown): SigmaReferenceDataset {
  if (!isRecord(value)) throw new SigmaReferenceError('The Sigma reference is not an object.');
  if (value.schemaVersion !== SIGMA_REFERENCE_SCHEMA_VERSION) {
    throw new SigmaReferenceError(
      `Unsupported Sigma reference schema version: ${String(value.schemaVersion)}.`,
    );
  }
  const specVersion = cleanText(value.specVersion);
  if (!specVersion) throw new SigmaReferenceError('The Sigma reference has no specification version.');

  return {
    schemaVersion: SIGMA_REFERENCE_SCHEMA_VERSION,
    specVersion,
    released: cleanText(value.released),
    retrieved: cleanText(value.retrieved),
    source: cleanText(value.source),
    sourcePath: cleanText(value.sourcePath),
    sourceSha256: cleanText(value.sourceSha256),
    modifiersPath: cleanText(value.modifiersPath),
    modifiersSha256: cleanText(value.modifiersSha256),
    license: cleanText(value.license),
    logSources: normalizeLogSources(value.logSources),
    fields: normalizeFields(value.fields),
    modifiers: normalizeModifiers(value.modifiers),
  };
}

export const SIGMA_REFERENCE_DATASET: SigmaReferenceDataset = normalizeSigmaReference(raw);

/** A stable key for de-duplicating logsource rows. */
export function logSourceKey(entry: SigmaLogSourceRef): string {
  return `${entry.product}|${entry.category}|${entry.service}`;
}

/** `category: process_creation · product: windows` */
export function logSourceSummary(entry: SigmaLogSourceRef): string {
  const parts: string[] = [];
  if (entry.category) parts.push(`category: ${entry.category}`);
  if (entry.product) parts.push(`product: ${entry.product}`);
  if (entry.service) parts.push(`service: ${entry.service}`);
  return parts.join(' · ');
}

export function logSourceIsEmpty(entry: SigmaLogSourceRef): boolean {
  return entry.product.length === 0 && entry.category.length === 0 && entry.service.length === 0;
}

function boundedLimit(value: number | undefined, fallback: number): number {
  const requested = Number.isFinite(value) ? Math.floor(value as number) : fallback;
  return Math.min(SIGMA_MAX_REFERENCE_RESULTS, Math.max(1, requested));
}

function normalizeFilter(value: string | undefined): string {
  return (value ?? '').trim().toLowerCase();
}

export function searchLogSources(
  query: string,
  options: SigmaLogSourceSearchOptions = {},
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): SigmaLogSourceRef[] {
  const needle = normalizeFilter(query);
  const product = normalizeFilter(options.product);
  const category = normalizeFilter(options.category);
  const service = normalizeFilter(options.service);
  const limit = boundedLimit(options.limit, 50);

  const matches = dataset.logSources.filter((entry) => {
    if (product && entry.product !== product) return false;
    if (category && entry.category !== category) return false;
    if (service && entry.service !== service) return false;
    if (needle.length === 0) return true;
    return (
      entry.product.includes(needle) ||
      entry.category.includes(needle) ||
      entry.service.includes(needle) ||
      entry.description.toLowerCase().includes(needle)
    );
  });

  if (needle.length === 0) {
    return matches
      .sort((left, right) => logSourceKey(left).localeCompare(logSourceKey(right)))
      .slice(0, limit);
  }

  const score = (entry: SigmaLogSourceRef): number => {
    const values = [entry.product, entry.category, entry.service].filter(Boolean);
    if (values.some((value) => value === needle)) return 0;
    if (values.some((value) => value.startsWith(needle))) return 1;
    if (values.some((value) => value.includes(needle))) return 2;
    if (entry.description.toLowerCase().includes(needle)) return 3;
    return 4;
  };

  return matches
    .sort(
      (left, right) =>
        score(left) - score(right) || logSourceKey(left).localeCompare(logSourceKey(right)),
    )
    .slice(0, limit);
}

function uniqueSorted(values: Iterable<string>): string[] {
  return [...new Set(values)].filter(Boolean).sort((left, right) => left.localeCompare(right));
}

export function logSourceProducts(
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): string[] {
  return uniqueSorted(dataset.logSources.map((entry) => entry.product));
}

export function logSourceCategories(
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): string[] {
  return uniqueSorted(dataset.logSources.map((entry) => entry.category));
}

export function logSourceServices(
  filter: { product?: string; category?: string } = {},
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): string[] {
  const product = normalizeFilter(filter.product);
  const category = normalizeFilter(filter.category);
  return uniqueSorted(
    dataset.logSources
      .filter((entry) => (!product || entry.product === product) && (!category || entry.category === category))
      .map((entry) => entry.service),
  );
}

export function isKnownLogSourceValue(
  part: SigmaLogSourcePart,
  value: string,
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): boolean {
  const cleaned = normalizeFilter(value);
  if (cleaned.length === 0) return true;
  return dataset.logSources.some((entry) => entry[part] === cleaned);
}

function fieldMatchesLogSource(field: SigmaFieldRef, entry: SigmaLogSourceRef): boolean {
  const checks: boolean[] = [];
  if (field.categories.length > 0) checks.push(field.categories.includes(entry.category));
  if (field.products.length > 0) checks.push(field.products.includes(entry.product));
  if (field.services.length > 0) checks.push(field.services.includes(entry.service));
  return checks.length > 0 && checks.every(Boolean);
}

/** Fields the taxonomy associates with a logsource, or an empty list when none are listed. */
export function fieldsForLogSource(
  entry: SigmaLogSourceRef,
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): SigmaFieldRef[] {
  if (logSourceIsEmpty(entry)) return [];
  return dataset.fields
    .filter((field) => fieldMatchesLogSource(field, entry))
    .sort((left, right) => left.name.localeCompare(right.name));
}

export function searchFields(
  query: string,
  options: SigmaFieldSearchOptions = {},
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): SigmaFieldRef[] {
  const needle = normalizeFilter(query);
  const category = normalizeFilter(options.category);
  const limit = boundedLimit(options.limit, 50);

  let candidates = dataset.fields;
  if (options.logSource) {
    candidates = fieldsForLogSource(options.logSource, dataset);
  } else if (category) {
    candidates = candidates.filter((field) => field.categories.includes(category));
  }

  const matches =
    needle.length === 0
      ? candidates
      : candidates.filter(
          (field) =>
            field.name.toLowerCase().includes(needle) ||
            field.description.toLowerCase().includes(needle) ||
            field.example.toLowerCase().includes(needle),
        );

  const score = (field: SigmaFieldRef): number => {
    const name = field.name.toLowerCase();
    if (name === needle) return 0;
    if (name.startsWith(needle)) return 1;
    if (name.includes(needle)) return 2;
    return 3;
  };

  return matches
    .sort((left, right) =>
      needle.length === 0
        ? left.name.localeCompare(right.name)
        : score(left) - score(right) || left.name.localeCompare(right.name),
    )
    .slice(0, limit);
}

export function describeSigmaField(
  name: string,
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): SigmaFieldRef | null {
  const cleaned = name.trim().toLowerCase();
  if (cleaned.length === 0) return null;
  return dataset.fields.find((field) => field.name.toLowerCase() === cleaned) ?? null;
}

export function isLocalTestModifier(name: string): boolean {
  return SIGMA_LOCAL_TEST_MODIFIERS.has(name.trim().toLowerCase());
}

export function searchModifiers(
  query: string,
  options: SigmaModifierSearchOptions = {},
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): SigmaModifierRef[] {
  const needle = normalizeFilter(query);
  const limit = boundedLimit(options.limit, 50);
  const matches = dataset.modifiers.filter((modifier) => {
    if (options.localTestOnly === true && !isLocalTestModifier(modifier.name)) return false;
    if (options.localTestOnly === false && isLocalTestModifier(modifier.name)) return false;
    if (needle.length === 0) return true;
    return (
      modifier.name.includes(needle) ||
      modifier.group.toLowerCase().includes(needle) ||
      modifier.description.toLowerCase().includes(needle)
    );
  });
  return matches.slice(0, limit);
}

export function modifierByName(
  name: string,
  dataset: SigmaReferenceDataset = SIGMA_REFERENCE_DATASET,
): SigmaModifierRef | null {
  const cleaned = name.trim().toLowerCase();
  if (cleaned.length === 0) return null;
  return dataset.modifiers.find((modifier) => modifier.name === cleaned) ?? null;
}
